int minIn[MAXN];

// Edmonds' (Chu-Liu) algorithm for minimum cost arborescence
long long edmonds(int root, int nodeCount, int edgeCount) {
    long long res = 0;
    int *id_arr = (int*)malloc((nodeCount+1)*sizeof(int));
    int *pre_arr = (int*)malloc((nodeCount+1)*sizeof(int));
    int *vis_arr = (int*)malloc((nodeCount+1)*sizeof(int));
    int *minIn_arr = (int*)malloc((nodeCount+1)*sizeof(int));

    // We'll work with a copy of edges
    // Use the global edges array

    int N = nodeCount;
    int M = edgeCount;

    while (1) {
        // Find minimum incoming edge for each node except root
        for (int i = 0; i < N; i++) minIn_arr[i] = INF;
        for (int i = 0; i < M; i++) {
            int u = edges[i].u, v = edges[i].v, w = edges[i].w;
            if (u != v && v != root && w < minIn_arr[v]) {
                minIn_arr[v] = w;
                pre_arr[v] = u;
            }
        }
        // Check if arborescence exists
        for (int i = 0; i < N; i++) {
            if (i != root && minIn_arr[i] == INF) {
                free(id_arr); free(pre_arr); free(vis_arr); free(minIn_arr);
                return -1;
            }
        }
        // Add minimum incoming edges to result
        for (int i = 0; i < N; i++) {
            if (i != root) res += minIn_arr[i];
        }
        // Detect cycles
        for (int i = 0; i < N; i++) id_arr[i] = -1, vis_arr[i] = -1;
        int cnt = 0;
        for (int i = 0; i < N; i++) {
            if (i == root) continue;
            int v = i;
            while (vis_arr[v] == -1 && id_arr[v] == -1 && v != root) {
                vis_arr[v] = i;
                v = pre_arr[v];
            }
            if (v != root && id_arr[v] == -1 && vis_arr[v] == i) {
                // Found a cycle, label it
                int u = v;
                do {
                    id_arr[u] = cnt;
                    u = pre_arr[u];
                } while (u != v);
                cnt++;
            }
        }
        if (cnt == 0) break; // No cycles, done
        // Nodes not in a cycle get their own id
        for (int i = 0; i < N; i++) {
            if (id_arr[i] == -1) id_arr[i] = cnt++;
        }
        // Contract cycles and update edges
        for (int i = 0; i < M; i++) {
            int v = edges[i].v;
            edges[i].u = id_arr[edges[i].u];
            edges[i].v = id_arr[edges[i].v];
            if (edges[i].u != edges[i].v) {
                edges[i].w -= minIn_arr[v];
            }
        }
        root = id_arr[root];
        N = cnt;
    }

    free(id_arr); free(pre_arr); free(vis_arr); free(minIn_arr);
    return res;
}

