    int u, v;
    ll w;
} Edge;

/*
  Chu-Liu/Edmonds' algorithm
  Returns minimum arborescence cost rooted at root.
  If impossible, returns -1.
*/
static ll directed_mst(int n, int root, int m, Edge *edges) {
    const ll INF = (1LL << 60);
    ll ans = 0;

    while (1) {
        ll *in = (ll *)malloc(sizeof(ll) * n);
        int *pre = (int *)malloc(sizeof(int) * n);

        for (int i = 0; i < n; i++) {
            in[i] = INF;
            pre[i] = -1;
        }

        for (int i = 0; i < m; i++) {
            int u = edges[i].u, v = edges[i].v;
            if (u != v && edges[i].w < in[v]) {
                in[v] = edges[i].w;
                pre[v] = u;
            }
        }

        in[root] = 0;

        for (int i = 0; i < n; i++) {
            if (in[i] == INF) {
                free(in);
                free(pre);
                return -1; // some vertex unreachable from root in arborescence sense
            }
        }

        int *id = (int *)malloc(sizeof(int) * n);
        int *vis = (int *)malloc(sizeof(int) * n);
        for (int i = 0; i < n; i++) {
            id[i] = -1;
            vis[i] = -1;
        }

        int cnt = 0;
        for (int i = 0; i < n; i++) ans += in[i];

        for (int i = 0; i < n; i++) {
            int v = i;
            while (vis[v] != i && id[v] == -1 && v != root) {
                vis[v] = i;
                v = pre[v];
            }
            if (v != root && id[v] == -1) {
                for (int u = pre[v]; u != v; u = pre[u]) id[u] = cnt;
                id[v] = cnt++;
            }
        }

        if (cnt == 0) {
            free(in);
            free(pre);
            free(id);
            free(vis);
            break; // no cycle
        }

        for (int i = 0; i < n; i++) {
            if (id[i] == -1) id[i] = cnt++;
        }

        Edge *new_edges = (Edge *)malloc(sizeof(Edge) * m);
        int new_m = 0;
        for (int i = 0; i < m; i++) {
            int u = id[edges[i].u];
            int v = id[edges[i].v];
            ll w = edges[i].w;
            if (u != v) {
                w -= in[edges[i].v];
                new_edges[new_m].u = u;
                new_edges[new_m].v = v;
                new_edges[new_m].w = w;
                new_m++;
            }
        }

        root = id[root];
        n = cnt;
        m = new_m;

        free(edges);
        edges = new_edges;

        free(in);
        free(pre);
        free(id);
        free(vis);
    }

    free(edges);
    return ans;
}

int main(void) {
    int V, E, r;
    if (scanf("%d %d %d", &V, &E, &r) != 3) return 0;

    Edge *edges = (Edge *)malloc(sizeof(Edge) * E);
    for (int i = 0; i < E; i++) {
        scanf("%d %d %lld", &edges[i].u, &edges[i].v, &edges[i].w);
    }

    ll ans = directed_mst(V, r, E, edges);
    printf("%lld\n", ans);
    return 0;
}

