long long minCostArborescence(int n, int r, vector<Edge>& edges) {
    long long res = 0;
    vector<int> id(n), prev_node(n), vis(n);

    while (true) {
        // For each node (except root), find minimum incoming edge
        vector<long long> minIn(n, LLONG_MAX);
        vector<int> minEdge(n, -1);

        for (int i = 0; i < (int)edges.size(); i++) {
            int u = edges[i].u, v = edges[i].v;
            long long w = edges[i].w;
            if (u != v && v != r && w < minIn[v]) {
                minIn[v] = w;
                minEdge[v] = u;
            }
        }

        // Check if all nodes are reachable
        for (int i = 0; i < n; i++) {
            if (i != r && minIn[i] == LLONG_MAX) return -1;
        }

        // Add minimum incoming edge weights
        for (int i = 0; i < n; i++) {
            if (i != r) res += minIn[i];
        }

        // Detect cycles
        fill(id.begin(), id.end(), -1);
        fill(vis.begin(), vis.end(), -1);
        int cnt = 0;

        for (int i = 0; i < n; i++) {
            int v = i;
            while (v != r && vis[v] == -1 && id[v] == -1) {
                vis[v] = i;
                v = minEdge[v];
            }
            if (v != r && id[v] == -1 && vis[v] == i) {
                // Found a cycle, label all nodes in cycle
                int u = v;
                do {
                    id[u] = cnt;
                    u = minEdge[u];
                } while (u != v);
                cnt++;
            }
        }

        if (cnt == 0) break; // No cycles, done

        // Assign non-cycle nodes their own id
        for (int i = 0; i < n; i++) {
            if (id[i] == -1) id[i] = cnt++;
        }

        // Update edges
        for (auto& e : edges) {
            int v = e.v;
            e.u = id[e.u];
            e.v = id[e.v];
            if (e.u != e.v) {
                e.w -= minIn[v];
            }
        }

        r = id[r];
        n = cnt;
        id.assign(n, -1);
        vis.assign(n, -1);
        prev_node.assign(n, -1);
    }

    return res;
}

