static const ll INF = (1LL << 62);

// Chu-Liu/Edmonds algorithm
// Returns minimum cost of arborescence rooted at root,
// or INF if it does not exist.
ll directed_mst(int n, int root, vector<Edge> edges) {
    ll res = 0;

    while (true) {
        vector<ll> in(n, INF);
        vector<int> pre(n, -1);

        // Find minimum incoming edge for each vertex
        for (const auto &e : edges) {
            if (e.u != e.v && e.w < in[e.v]) {
                in[e.v] = e.w;
                pre[e.v] = e.u;
            }
        }

        in[root] = 0;

        // If some vertex except root has no incoming edge, impossible
        for (int i = 0; i < n; ++i) {
            if (in[i] == INF) return INF;
        }

        // Detect cycles
        int cnt = 0;
        vector<int> id(n, -1), vis(n, -1);

        for (int i = 0; i < n; ++i) res += in[i];

        for (int i = 0; i < n; ++i) {
            int v = i;
            while (vis[v] != i && id[v] == -1 && v != root) {
                vis[v] = i;
                v = pre[v];
            }
            if (v != root && id[v] == -1) {
                for (int u = pre[v]; u != v; u = pre[u]) id[u] = cnt;
                id[v] = cnt++;
            }
        }

        // No cycle
        if (cnt == 0) break;

        // Assign ids to non-cycle vertices
        for (int i = 0; i < n; ++i) {
            if (id[i] == -1) id[i] = cnt++;
        }

        // Contract cycles
        vector<Edge> new_edges;
        new_edges.reserve(edges.size());
        for (const auto &e : edges) {
            int u = id[e.u];
            int v = id[e.v];
            ll w = e.w;
            if (u != v) {
                w -= in[e.v];
                new_edges.push_back({u, v, w});
            }
        }

        root = id[root];
        n = cnt;
        edges.swap(new_edges);
    }

    return res;
}

