    }

    static long minimumCostArborescence(int n, List<Edge> edges, int root) {
        long cost = 0;
        int[] parent = new int[n];
        int[] used = new int[n];
        int[] comp = new int[n];
        long[] minIn = new long[n];
        Arrays.fill(minIn, INF);
        Arrays.fill(parent, -1);

        while (true) {
            Arrays.fill(minIn, INF);
            for (Edge e : edges) {
                if (e.u != e.v && e.w < minIn[e.v]) {
                    minIn[e.v] = e.w;
                    parent[e.v] = e.u;
                }
            }

            minIn[root] = 0;
            for (int i = 0; i < n; i++) {
                if (minIn[i] == INF) return -1; // no arborescence
            }

            int cnt = 0;
            Arrays.fill(used, -1);
            Arrays.fill(comp, -1);
            for (int i = 0; i < n; i++) {
                cost += minIn[i];
                int v = i;
                while (used[v] != i && comp[v] == -1 && v != root) {
                    used[v] = i;
                    v = parent[v];
                }
                if (v != root && comp[v] == -1) {
                    for (int u = parent[v]; u != v; u = parent[u]) {
                        comp[u] = cnt;
                    }
                    comp[v] = cnt++;
                }
            }

