            for (int i = 0; i < n; i++) {
                if (comp[i] == -1) {
                    comp[i] = cnt++;
                }
            }

            List<Edge> newEdges = new ArrayList<>();
            for (Edge e : edges) {
                int nu = comp[e.u];
                int nv = comp[e.v];
                if (nu != nv) {
                    newEdges.add(new Edge(nu, nv, e.w - minIn[e.v]));
                }
            }

            edges = newEdges;
            root = comp[root];
            n = cnt;
        }

        return cost;
    }
}

