                    minCost[v[i]] = w[i];
                    prev[v[i]] = u[i];
                }
            }

            // Check if all nodes are reachable
            for (int i = 0; i < n; i++) {
                if (i != root && minCost[i] == Long.MAX_VALUE) {
                    return -1; // No arborescence exists
                }
            }

            // Add minimum costs to result
            // Detect cycles
            Arrays.fill(id, -1);
            int[] visited = new int[n];
            Arrays.fill(visited, -1);
            int cnt = 0;

            for (int i = 0; i < n; i++) {
                result += (i != root ? minCost[i] : 0);
                int cur = i;
                while (visited[cur] == -1 && id[cur] == -1 && cur != root) {
                    visited[cur] = i;
                    cur = prev[cur];
                }
