            // Assign non-cycle nodes their own id
            for (int i = 0; i < n; i++) {
                if (id[i] == -1) {
                    id[i] = cnt++;
                }
            }

            // Contract cycles and update edges
            for (int i = 0; i < m; i++) {
                int pu = id[u[i]];
                int pv = id[v[i]];
                u[i] = pu;
                if (pu != pv) {
