        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
                if (c == -1) return Long.MIN_VALUE;
            } while (c <= ' ');

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static class Edge {
        int from, to;
        long w;

        Edge(int from, int to, long w) {
            this.from = from;
            this.to = to;
            this.w = w;
        }
    }

    static final long INF = Long.MAX_VALUE / 4;

    static long directedMST(int n, int root, List<Edge> edges) {
        long res = 0;

        while (true) {
            long[] in = new long[n];
            int[] pre = new int[n];
            Arrays.fill(in, INF);
            Arrays.fill(pre, -1);

            // Find minimum incoming edge for each vertex
            for (Edge e : edges) {
                if (e.from != e.to && e.w < in[e.to]) {
                    in[e.to] = e.w;
                    pre[e.to] = e.from;
                }
            }

            in[root] = 0;

            // If some vertex other than root has no incoming edge, impossible
            for (int i = 0; i < n; i++) {
                if (in[i] == INF) return -1;
            }

            // Detect cycles
            int cntCycle = 0;
            int[] id = new int[n];
            int[] vis = new int[n];
            Arrays.fill(id, -1);
            Arrays.fill(vis, -1);

            for (int i = 0; i < n; i++) {
                res += in[i];
                int v = i;
                while (vis[v] != i && id[v] == -1 && v != root) {
                    vis[v] = i;
                    v = pre[v];
                }
                if (v != root && id[v] == -1) {
                    for (int u = pre[v]; u != v; u = pre[u]) {
                        id[u] = cntCycle;
                    }
                    id[v] = cntCycle++;
                }
            }

            if (cntCycle == 0) break; // no cycle

            for (int i = 0; i < n; i++) {
                if (id[i] == -1) id[i] = cntCycle++;
            }

            List<Edge> newEdges = new ArrayList<>();
            for (Edge e : edges) {
                int u = id[e.from];
                int v = id[e.to];
                long w = e.w;
                if (u != v) {
                    w -= in[e.to];
                    newEdges.add(new Edge(u, v, w));
                }
            }

            root = id[root];
            n = cntCycle;
            edges = newEdges;
        }

        return res;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        long first = fs.nextLong();
        if (first == Long.MIN_VALUE) return;

        int n = (int) first;
        int m = fs.nextInt();
        int r = fs.nextInt();

        int[] u = new int[m];
        int[] v = new int[m];
        long[] w = new long[m];

        int minVertex = Integer.MAX_VALUE;
        for (int i = 0; i < m; i++) {
            u[i] = fs.nextInt();
            v[i] = fs.nextInt();
            w[i] = fs.nextLong();
            minVertex = Math.min(minVertex, Math.min(u[i], v[i]));
        }
        minVertex = Math.min(minVertex, r);

        // Support both 0-indexed and 1-indexed input
        int shift = (minVertex == 0 ? 0 : 1);

        List<Edge> edges = new ArrayList<>(m);
        for (int i = 0; i < m; i++) {
            edges.add(new Edge(u[i] - shift, v[i] - shift, w[i]));
        }
        r -= shift;

        long ans = directedMST(n, r, edges);
        if (ans == -1) {
            System.out.println("Impossible");
        } else {
            System.out.println(ans);
        }
    }
}

import sys

class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0] * n

    def find(self, x):
        while self.parent[x] != x:
            self.parent[x] = self.parent[self.parent[x]]
            x = self.parent[x]
        return x

    def union(self, x, y):
        rx, ry = self.find(x), self.find(y)
        if rx == ry:
            return False
        if self.rank[rx] < self.rank[ry]:
            self.parent[rx] = ry
        elif self.rank[rx] > self.rank[ry]:
            self.parent[ry] = rx
        else:
            self.parent[ry] = rx
            self.rank[rx] += 1
        return True

def min_cost_arborescence(n, edges, root):
    INF = 10**18
    cost = [INF] * n
    parent = [-1] * n
    used = [False] * n
    comp = list(range(n))

    res = 0
    while True:
        cost = [INF] * n
        parent = [-1] * n
        for u, v, w in edges:
            if u != v and w < cost[v]:
                cost[v] = w
                parent[v] = u

        cost[root] = 0
        for i in range(n):
            if cost[i] == INF and comp[i] == i:
                return None  # No arborescence

        # Step 2: find cycles
        visited = [-1] * n
        last = 0
        cycles = []
        for i in range(n):
            if comp[i] != i or i == root:
                continue
            path = []
            v = i
            while visited[v] == -1 and v != root:
                visited[v] = last
                path.append(v)
                v = parent[v]
            if v != root and visited[v] == last:
                # cycle found
                cycle = []
                idx = path.index(v)
                for node in path[idx:]:
                    cycle.append(node)
                cycles.append(cycle)
            last += 1

        if not cycles:
            break

        # Step 3: contract cycles
        new_id = [i for i in range(n)]
        for cycle in cycles:
            cycle_cost = sum(cost[v] for v in cycle)
            res += cycle_cost
            for v in cycle:
                new_id[v] = cycle[0]
            # Update edges incoming to cycle
            new_edges = []
            for u, v, w in edges:
                if new_id[u] != new_id[v]:
                    if new_id[v] in (new_id[x] for x in cycle):
                        w -= cost[v]
                    new_edges.append((new_id[u], new_id[v], w))
            edges = new_edges
            # Update component mapping
            for v in cycle:
                comp[v] = cycle[0]
        # Rebuild graph with contracted nodes
        n = len(set(new_id))
        id_map = {}
        new_nodes = []
        for i in range(len(new_id)):
            if new_id[i] not in id_map:
                id_map[new_id[i]] = len(id_map)
                new_nodes.append(new_id[i])
        edges = [(id_map[u], id_map[v], w) for u, v, w in edges]
        root = id_map[new_id[root]]
        comp = list(range(n))

    # Add cost of selected edges
    for i in range(n):
        if i != root:
            res += cost[i]
    return res

def solve():
    input_data = sys.stdin.read().strip().split()
    if not input_data:
        return
    it = iter(input_data)
    n = int(next(it))
    m = int(next(it))
    r = int(next(it))
    edges = []
    for _ in range(m):
        u = int(next(it))
        v = int(next(it))
        w = int(next(it))
        edges.append((u, v, w))

    ans = min_cost_arborescence(n, edges, r)
    if ans is None:
        print("NO")
    else:
        print(ans)

if __name__ == "__main__":
    solve()
